/** Category driving which indicator icon shows for an active encounter. */
export type EncntrIndicatorCategory =
  | 'emergency'
  | 'inpatient'
  | 'other'
  | 'observation'
  | 'day-surgery'
  | 'recurring'
  | 'outpatient'
  | 'long-term-care'
  | 'palliative-hospice'
  | 'virtual-telehealth';

/**
 * Explicit config mapping wins; otherwise a display name containing "emerg"
 * reads as emergency so ED patients look right before an admin ever maps
 * categories in the Config page (stakeholder decision 2026-07-06). The
 * seven additional categories beyond emergency/inpatient/other are only
 * reachable via an explicit mapping — there is no keyword default for them.
 */
export function resolveEncntrIndicatorCategory(
  typeCd: number,
  typeDisplay: string,
  categories?: Record<string, EncntrIndicatorCategory>
): EncntrIndicatorCategory {
  const mapped = categories?.[String(typeCd)];
  if (mapped) return mapped;
  return /emerg/i.test(typeDisplay) ? 'emergency' : 'inpatient';
}

export interface EncntrIndicatorDef {
  category: EncntrIndicatorCategory;
  label: string;
  /** CSS class applied alongside .encntr-indicator (existing classes preserved) */
  cssClass: string;
}

