/**
 * Display value for a schedule-list cell. Attending shows only the true
 * encounter attending (ATTENDDOC relation); when there is none the cell is
 * an em dash — no ordering-provider or resource substitution (stakeholder
 * decision 2026-07-03: a name under "Attending" must be the attending).
 */
export function cellDisplayValue(appt: ScheduleAppointment, key: string): string {
  if (key === 'attending_physician') {
    return appt.attending_physician || '—';
  }
  return ((appt as unknown as Record<string, unknown>)[key] as string | undefined) ?? '—';
}

